<script setup>
import {ref,onMounted,onUnmounted,computed} from 'vue';import {useRouter,useRoute} from 'vue-router';import {store,api,cargar,alertas} from './store';
const listo=ref(false),error=ref(''),form=ref({email:'',password:''}),ocupado=ref(false),reloj=ref(0);
const router=useRouter(),route=useRoute();const menusEstudiante=[['/','Resumen','bi-grid-1x2'],['/mis-notas','Mis calificaciones','bi-journal-check'],['/cursos','Mis cursos','bi-book'],['/actividades','Actividades','bi-list-check'],['/planificador','Planificador','bi-kanban'],['/calendario','Calendario','bi-calendar3'],['/progreso','Progreso','bi-bar-chart'],['/alertas','Alertas','bi-bell']];
const menusDocente=[['/docente','Resumen docente','bi-grid-1x2'],['/registros','Calificaciones','bi-people'],['/analisis','Rendimiento','bi-graph-up-arrow'],['/historial','Reportes e historial','bi-folder2-open']];const esDocente=computed(()=>store.usuario?.rol==='docente');const esAdmin=computed(()=>store.usuario?.rol==='admin');const menus=computed(()=>esAdmin.value?[['/admin','Gestión de usuarios','bi-people']]:esDocente.value?menusDocente:menusEstudiante);async function ajustarRuta(){await router.isReady();if((route.meta.rol||'estudiante')!==store.usuario?.rol)await router.replace(esAdmin.value?'/admin':esDocente.value?'/docente':'/')}
const avisos=computed(()=>{reloj.value;return alertas().length});let timer;
onMounted(async()=>{timer=setInterval(()=>reloj.value++,60000);try{store.usuario=await api('/me');await cargar();await ajustarRuta()}catch(e){store.usuario=null}finally{listo.value=true}});
onUnmounted(()=>clearInterval(timer));
async function entrar(){error.value='';ocupado.value=true;try{store.usuario=await api('/login','POST',form.value);await cargar();await ajustarRuta();form.value.password=''}catch(e){store.usuario=null;error.value=e.message}finally{ocupado.value=false}}
async function salir(){try{await api('/logout','POST');store.usuario=null;store.cursos=[];store.tareas=[];error.value='';await router.replace('/')}catch(e){error.value=e.message}}
</script>
<template><div v-if="!listo" class="p-5">Cargando StudyPlan…</div><div v-else-if="!store.usuario" class="login"><div class="login-intro"><div class="brand"><span class="brand-icon"><i class="bi bi-mortarboard-fill"></i></span>StudyPlan</div><div><div class="eyebrow text-white-50">TU SEMESTRE, ORGANIZADO</div><h1>Estudia con un plan.<br>Avanza con confianza.</h1><p>Centraliza tus cursos, controla tus entregas y cumple tus objetivos académicos.</p></div><div class="login-features"><span><i class="bi bi-calendar-check"></i> Calendario académico</span><span><i class="bi bi-bell"></i> Alertas de entrega</span><span><i class="bi bi-bar-chart"></i> Seguimiento del progreso</span></div></div><div class="login-form"><form @submit.prevent="entrar"><div class="eyebrow">PLATAFORMA ACADÉMICA</div><h2>Bienvenido a StudyPlan</h2><p class="text-secondary mb-4">Ingresa con la cuenta asignada por administración.</p><div v-if="error" class="alert alert-danger">{{error}}</div><label class="mb-3 w-100">Correo electrónico<input class="form-control" type="email" v-model="form.email" required placeholder="estudiante@correo.com"></label><label class="mb-3 w-100">Contraseña<input class="form-control" type="password" v-model="form.password" minlength="8" required placeholder="Mínimo 8 caracteres"></label><button class="btn btn-primary w-100" :disabled="ocupado">{{ocupado?'Procesando…':'Iniciar sesión'}}</button></form></div></div>
<div v-else class="layout"><aside class="sidebar"><div class="brand"><span class="brand-icon"><i class="bi bi-mortarboard-fill"></i></span>StudyPlan</div><div class="sidebar-caption">ESPACIO ACADÉMICO</div><nav class="nav flex-column gap-1"><RouterLink v-for="m in menus" :key="m[0]" :to="m[0]" class="nav-link" exact-active-class="active"><i :class="['bi',m[2]]"></i><span>{{m[1]}}</span><span v-if="m[0]==='/alertas'&&avisos" class="nav-count">{{avisos}}</span></RouterLink></nav><div class="sidebar-footer"><div class="avatar">{{store.usuario.nombre.slice(0,1).toUpperCase()}}</div><div class="overflow-hidden"><strong class="d-block text-truncate">{{store.usuario.nombre}}</strong><small class="text-white-50">{{esAdmin?'Administrador':esDocente?'Docente / tutor':'Estudiante'}}</small></div></div></aside><main><header class="topbar"><div><strong>{{esAdmin?'Administración':esDocente?'Panel docente':'Mi espacio académico'}}</strong><div class="small text-secondary">{{new Date().toLocaleDateString('es-PE',{weekday:'long',day:'numeric',month:'long'})}}</div></div><div class="d-flex align-items-center gap-3"><RouterLink v-if="!esDocente&&!esAdmin" to="/alertas" class="notification-button" aria-label="Alertas"><i class="bi bi-bell"></i><span v-if="avisos">{{avisos}}</span></RouterLink><button class="btn btn-outline-secondary btn-sm" @click="salir"><i class="bi bi-box-arrow-right me-1"></i> Salir</button></div></header><div class="workspace"><p v-if="error" class="alert alert-danger">{{error}}</p><RouterView/></div></main></div></template>